import{at as e,it as t,n,vt as r}from"./chunks/framework.BmH7hI6Z.js";var i=JSON.parse(`{"title":"Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/solid-protocol/limitations.md","filePath":"guide/solid-protocol/limitations.md"}`),a={name:`guide/solid-protocol/limitations.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h1><p>Given the nature of Solid and RDF, there are some things to keep in mind when declaring your schemas:</p><ul><li>RDF can&#39;t represent <code>null</code> values, so <code>null</code> and <code>undefined</code> attributes will both be stored as missing properties.</li><li>In array fields, an empty array will also be stored as a missing property. You can use <code>.default([])</code> in your field definitions to make sure that you always get an array.</li></ul><div class="warning custom-block"><p class="custom-block-title">TODO</p><p>Review the rest of the limitations from previous versions of Soukai, and confirm whether they still apply in soukai-bis:</p><ul><li><a href="https://github.com/NoelDeMartin/soukai/issues/9" target="_blank" rel="noreferrer">#9</a> Object fields cannot be used, use relationships instead. Neither can nested arrays.</li><li><a href="https://github.com/NoelDeMartin/soukai/issues/9" target="_blank" rel="noreferrer">#9</a> Arrays cannot have duplicated entries, given that RDF is monotonic.</li><li><a href="https://github.com/NoelDeMartin/soukai/issues/5" target="_blank" rel="noreferrer">#5</a> Blank nodes are not supported.</li></ul></div>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};